package com.fooddelivery.restaurant.entity;import java.util.*;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("restaurants") public class Restaurant{@Id private String id;private String name,address,cuisine;private boolean open=true;private List<MenuItem> menu=new ArrayList<>();public String getId(){return id;}public void setId(String v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getCuisine(){return cuisine;}public void setCuisine(String v){cuisine=v;}public boolean isOpen(){return open;}public void setOpen(boolean v){open=v;}public List<MenuItem> getMenu(){return menu;}public void setMenu(List<MenuItem> v){menu=v;}}
